package com.phoenix.business.repository; import com.phoenix.business.domain.Attendance; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.domain.*; import java.time.Instant; import java.util.*; public interface AttendanceRepository extends JpaRepository<Attendance,Long>{Optional<Attendance> findFirstByMemberIdAndStatusOrderByCheckedInAtDesc(Long id,Attendance.Status status); Page<Attendance> findByCheckedInAtBetween(Instant a,Instant b,Pageable p); List<Attendance> findTop10ByMemberIdOrderByCheckedInAtDesc(Long id); long countByCheckedInAtBetween(Instant a,Instant b);}
